# Inglenook for hexyl: Inglenook Day.
# Source this from your profile. Needs hexyl 0.17 or newer.
# Palette 1.0.0, https://github.com/mookeyj79/Inglenook

# The offset column on the left.
$env:HEXYL_COLOR_OFFSET = '#657178'
# The null byte.
$env:HEXYL_COLOR_NULL = '#657178'
# Printable ASCII characters.
$env:HEXYL_COLOR_ASCII_PRINTABLE = '#407135'
# Spaces, tabs and line breaks.
$env:HEXYL_COLOR_ASCII_WHITESPACE = '#49545d'
# Other ASCII bytes, such as control characters.
$env:HEXYL_COLOR_ASCII_OTHER = '#915023'
# Bytes above 0x7F.
$env:HEXYL_COLOR_NONASCII = '#844b80'
